var ral_vars=new Array;function ral_show(e,t,n){var o=t?"block":"none";if(ral_vars.div=e,null!=n){var r=findPos(n);r.top=0,document.getElementById(e).style.left="33%",document.getElementById(e).style.top=r.top+"px",document.documentElement.clientWidth<r.left+600&&(document.getElementById(e).style.left=r.left-550+"px")}document.getElementById(e).style.display=o,document.body.onmousedown=function(t){checkParent(t&&t.target||event&&event.srcElement,e)||ral_show(e,!1)}}function article_ral_select(e,t,n,o,r){document.getElementById("lst_ral_"+e+"_"+t).value=n,document.getElementById(ral_vars.div).style.display="none",checkOption($("#option"+t),r,e,t,"",!0,o)}function panier_ral_select(e,e,t,n){var o=document.getElementsByName("lst_caract["+ral_vars.lignepanierid+"]["+ral_vars.caractid+"]");for(i=0;i<o.length;i++)o[i].checked&&(o[i].value=t);document.formu.submit()}function set_ral_vars(e){ral_vars=e}function findPos(e){var t=curtop=0;if(e.offsetParent)do{t+=e.offsetLeft,curtop+=e.offsetTop}while(e=e.offsetParent);return{left:t,top:curtop}}function checkParent(e,t){for(;e.parentNode;){if(e==document.getElementById(t))return!0;e=e.parentNode}return!1}